import { defineStore } from 'pinia';
import { ref, computed, watch } from 'vue';
import { useDebounceFn, useEventListener } from '@vueuse/core';
import { LocalStorage, SessionStorage } from 'quasar';
import { guessLocationFromTimezone } from '@services/timezone-location';

/**
 * Local Properties Store
 *
 * Purpose: Device-specific, ephemeral app state
 * Storage: Mix of localStorage (persistent) and sessionStorage (session-only)
 * Sync Strategy: Never sync (local-only) - NO cross-tab sync for location
 *
 * These properties are:
 * - Device-specific (different on mobile vs desktop)
 * - Ephemeral (current session state)
 * - Privacy-sensitive (current location, etc.)
 * - Never synced to server
 * - Location does NOT sync across tabs (each tab is independent)
 */

/**
 * Location state (map viewport)
 */
export interface LocationState {
  lat: number;
  lng: number;
  zoom: number;
  bearing?: number;
  pitch?: number;
  timestamp: number;
  /** Where this position came from — drives the initial-location lifecycle:
   *  'guess' (timezone-based first-visit start) and 'default' (Alps) are
   *  replaced on every user map movement, which persists 'user'. A 'user'
   *  position is the sticky "where I was last" and wins on every return
   *  visit. Entries written before this field existed count as 'user'. */
  source?: 'guess' | 'user' | 'default';
}

/**
 * Session state (ephemeral, cleared on browser close)
 */
export interface SessionState {
  startTime: number;
  clipboard?: [number, number]; // [lat, lng]
  lastActiveTab: string;
}

/**
 * Local properties interface
 */
export interface LocalProperties {
  location: LocationState;
}

/**
 * Default values
 */
const defaultLocationState: LocationState = {
  lat: 46.8, // Switzerland center (Alps)
  lng: 8.2,
  zoom: 8,
  bearing: 0,
  pitch: 0,
  timestamp: Date.now(),
  source: 'default',
};

/** Zoom used for the timezone-based first-visit guess — deliberately
 *  region-level (the guess is timezone-coarse, not user-specific). */
const GUESS_ZOOM = 6;

const defaultSessionState: SessionState = {
  startTime: Date.now(),
  lastActiveTab: 'map',
};

export const useLocalPropertiesStore = defineStore('localProperties', () => {
  // SSR Guard: Return defaults on server
  if (typeof window === 'undefined') {
    const defaultStateRef = ref({
      location: { ...defaultLocationState },
      session: { ...defaultSessionState },
    });
    return {
      persistentState: defaultStateRef,
      sessionState: ref({ ...defaultSessionState }),
      currentLocation: computed(() => defaultLocationState),
      sessionStartTime: computed(() => Date.now()),
      clipboardLocation: computed(() => undefined),
      lastActiveTab: computed(() => 'map'),
      updateLocation: () => {},
      setLocation: () => {},
      getLastKnownLocation: () => defaultLocationState,
      isLocationStale: () => true,
      forceSave: () => {},
      resetLocation: () => {},
      updateSession: () => {},
      setClipboardLocation: () => {},
      setLastActiveTab: () => {},
      parseLocationFromHash: () => null,
      getInitialLocation: () => ({ ...defaultLocationState }),
      clearAll: () => {},
    };
  }

  // Storage keys with namespace
  const STORAGE_KEY = 'wodore:localProperties';
  const SESSION_STORAGE_KEY = 'wodore:localPropertiesSession';

  // ========================================
  // Persistent state (localStorage)
  // NOTE: Using manual LocalStorage instead of useStorage to prevent cross-tab sync
  // Each tab reads localStorage on init, but writes don't trigger updates in other tabs
  // ========================================

  // Reactive state (not synced across tabs)
  const persistentState = ref<LocalProperties>({
    location: { ...defaultLocationState },
  });

  // Load from localStorage on initialization (one-time read)
  const loadFromStorage = (): LocalProperties => {
    try {
      const stored = LocalStorage.getItem(STORAGE_KEY) as LocalProperties | null;
      if (stored) {
        // Quasar already parses JSON
        return {
          location: {
            ...defaultLocationState,
            ...stored.location,
          },
        };
      }
    } catch {
      // Silent error handling
    }
    return { location: { ...defaultLocationState } };
  };

  // Initialize from storage
  persistentState.value = loadFromStorage();

  // Save to localStorage (debounced to 1 second for live updates)
  const saveToStorage = useDebounceFn(() => {
    LocalStorage.set(STORAGE_KEY, persistentState.value);
  }, 1000); // 1 second debounce for live updates

  // Watch for changes and save to localStorage
  watch(
    persistentState,
    () => {
      saveToStorage();
    },
    { deep: true }
  );

  // Save immediately on initialization to ensure key exists
  if (!LocalStorage.hasItem(STORAGE_KEY)) {
    LocalStorage.set(STORAGE_KEY, persistentState.value);
  }

  // ========================================
  // Session-only state (sessionStorage)
  // NOTE: SessionStorage is naturally isolated per tab, so useStorage is fine here
  // ========================================
  const sessionState = ref<SessionState>({ ...defaultSessionState });

  // Load session state from sessionStorage
  const loadSessionFromStorage = (): SessionState => {
    try {
      const stored = SessionStorage.getItem(SESSION_STORAGE_KEY) as SessionState | null;
      if (stored) {
        return stored; // Quasar already parses JSON
      }
    } catch {
      // Silent error handling
    }
    return { ...defaultSessionState };
  };

  // Save session state to sessionStorage
  const saveSessionToStorage = () => {
    SessionStorage.set(SESSION_STORAGE_KEY, sessionState.value);
  };

  // Initialize session state
  sessionState.value = loadSessionFromStorage();

  // Watch for changes and save to sessionStorage
  watch(
    sessionState,
    () => {
      saveSessionToStorage();
    },
    { deep: true }
  );

  // ========================================
  // Computed properties
  // ========================================
  const currentLocation = computed(() => persistentState.value.location);
  const sessionStartTime = computed(() => sessionState.value.startTime);
  const clipboardLocation = computed(() => sessionState.value.clipboard);
  const lastActiveTab = computed(() => sessionState.value.lastActiveTab);

  // ========================================
  // Location management
  // ========================================

  /**
   * Update current location (map viewport)
   * Automatically debounced (15 seconds)
   */
  const updateLocation = (location: Partial<LocationState>) => {
    Object.assign(persistentState.value.location, location, {
      timestamp: Date.now(),
      source: 'user',
    });
    // Watcher will trigger debounced save automatically
  };

  /**
   * Set complete location state
   * Automatically debounced (15 seconds)
   */
  const setLocation = (location: LocationState) => {
    persistentState.value.location = {
      ...location,
      timestamp: Date.now(),
    };
    // Watcher will trigger debounced save automatically
  };

  /**
   * Get last known location
   */
  const getLastKnownLocation = (): LocationState => {
    return persistentState.value.location;
  };

  /**
   * Check if location is stale (older than specified minutes)
   */
  const isLocationStale = (maxAgeMinutes: number = 60): boolean => {
    const age = Date.now() - persistentState.value.location.timestamp;
    const maxAgeMs = maxAgeMinutes * 60 * 1000;
    return age > maxAgeMs;
  };

  /**
   * Force immediate save (for page close, etc.)
   * Overrides the debounced save
   */
  const forceSave = () => {
    LocalStorage.set(STORAGE_KEY, persistentState.value);
  };

  // ========================================
  // Session management
  // ========================================

  /**
   * Update session state
   */
  const updateSession = (session: Partial<SessionState>) => {
    Object.assign(sessionState.value, session);
  };

  /**
   * Set clipboard location
   */
  const setClipboardLocation = (location: [number, number] | undefined) => {
    sessionState.value.clipboard = location;
  };

  /**
   * Set last active tab
   */
  const setLastActiveTab = (tab: string) => {
    sessionState.value.lastActiveTab = tab;
  };

  // ========================================
  // Page lifecycle handlers
  // ========================================

  /**
   * Handle page close/hide
   * Save location immediately before closing
   */
  const handleBeforeUnload = () => {
    forceSave();
  };

  const handleVisibilityChange = () => {
    if (document.hidden) {
      // Page is being hidden (user switched tabs, minimized, etc.)
      forceSave();
    }
  };

  // Register event listeners for page lifecycle
  useEventListener(window, 'beforeunload', handleBeforeUnload);
  useEventListener(document, 'visibilitychange', handleVisibilityChange);

  // ========================================
  // Reset and clear
  // ========================================

  /**
   * Reset location to defaults
   */
  const resetLocation = () => {
    persistentState.value.location = { ...defaultLocationState };
  };

  /**
   * Clear all local properties
   */
  const clearAll = () => {
    persistentState.value.location = { ...defaultLocationState };
    sessionState.value = { ...defaultSessionState };
  };

  // ========================================
  // URL hash parsing
  // ========================================

  /**
   * Parse location from URL hash
   * Format: #map=zoom/lat/lng
   * Example: #map=13.77/46.13591/6.81813
   */
  const parseLocationFromHash = (): LocationState | null => {
    const hash = window.location.hash;
    if (!hash || !hash.startsWith('#map=')) {
      return null;
    }

    try {
      const parts = hash.substring('#map='.length).split('/');
      if (parts.length !== 3) {
        return null;
      }

      const zoom = parseFloat(parts[0]);
      const lat = parseFloat(parts[1]);
      const lng = parseFloat(parts[2]);

      if (isNaN(zoom) || isNaN(lat) || isNaN(lng)) {
        return null;
      }

      return {
        lat,
        lng,
        zoom,
        bearing: 0,
        pitch: 0,
        timestamp: Date.now(),
      };
    } catch (error) {
      console.error('[local-properties] Failed to parse location from hash:', error);
      return null;
    }
  };

  /**
   * Get initial location for map
   * Priority:
   * 1. URL hash location (shared/deep links)
   * 2. Last USER position from storage (any age — the map always reopens
   *    where the user last looked; only movement sets 'user')
   * 3. First visit / never moved: timezone-based guess, persisted so it
   *    stays stable within a timezone — replaces the old 60-minute expiry
   *    that sent every returning user back to the Alps default
   * 4. Default location (Alps) when the timezone gives no signal
   */
  const getInitialLocation = (): LocationState => {
    // Check URL hash first
    const hashLocation = parseLocationFromHash();
    if (hashLocation) {
      return hashLocation;
    }

    // Check last known location — sticky once the user moved the map
    const lastLocation = persistentState.value.location;
    const storedSource = lastLocation.source ?? 'user'; // legacy entries
    if (storedSource === 'user') {
      return { ...lastLocation, source: storedSource };
    }

    // First visit (or user never moved the map yet): guess from the
    // timezone — permission-free, offline, region-level accuracy. The
    // guess is persisted so the next visit starts from the same spot
    // until real map movement takes over.
    const guess = guessLocationFromTimezone();
    const initial: LocationState = guess
      ? {
          lat: guess.lat,
          lng: guess.lng,
          zoom: GUESS_ZOOM,
          bearing: 0,
          pitch: 0,
          timestamp: Date.now(),
          source: 'guess',
        }
      : { ...defaultLocationState, timestamp: Date.now() };
    setLocation(initial);
    return initial;
  };

  return {
    // State
    persistentState,
    sessionState,

    // Computed
    currentLocation,
    sessionStartTime,
    clipboardLocation,
    lastActiveTab,

    // Location actions
    updateLocation,
    setLocation,
    getLastKnownLocation,
    isLocationStale,
    forceSave,
    resetLocation,

    // Session actions
    updateSession,
    setClipboardLocation,
    setLastActiveTab,

    // URL hash
    parseLocationFromHash,
    getInitialLocation,

    // Reset
    clearAll,
  };
});
